package com.ryanjei.orushio.pve.paper;
import com.ryanjei.orushio.pve.application.GameThreadExecutor;import com.ryanjei.orushio.pve.map.*;import org.bukkit.*;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.Plugin;import java.time.Duration;import java.util.UUID;
public final class PaperMapWorldGateway implements MapWorldGateway{public static final String TOOL_KEY="setup_tool";private final Plugin plugin;private final GameThreadExecutor executor;private final NamespacedKey key;public PaperMapWorldGateway(Plugin plugin,GameThreadExecutor executor){this.plugin=plugin;this.executor=executor;this.key=new NamespacedKey(plugin,TOOL_KEY);}@Override public void loadForSetup(TemporaryWorldManager.OwnedWorld owned,UUID administrator){execute(()->{var player=Bukkit.getPlayer(administrator);validateAdministrator(player!=null,player!=null&&player.isOp(),player!=null&&player.hasPermission("orushio.pve.admin"));World world=null;try{world=Bukkit.createWorld(new WorldCreator(owned.worldName()));if(world==null)throw new IllegalStateException("セットアップワールドをロードできません。");ItemStack tool=new ItemStack(Material.BLAZE_ROD);ItemMeta meta=tool.getItemMeta();meta.setDisplayName("マップ設定ツール");meta.getPersistentDataContainer().set(key,PersistentDataType.BYTE,(byte)1);tool.setItemMeta(meta);player.getInventory().addItem(tool);if(!player.teleport(world.getSpawnLocation()))throw new IllegalStateException("管理者をセットアップワールドへ転送できません。");return null;}catch(RuntimeException failure){if(world!=null)try{rollbackLoadedWorld(world);}catch(RuntimeException rollback){failure.addSuppressed(rollback);}throw failure;}});}@Override public void unload(TemporaryWorldManager.OwnedWorld owned){execute(()->{World world=Bukkit.getWorld(owned.worldName());if(world==null)return null;rollbackLoadedWorld(world);return null;});}static void validateAdministrator(boolean online,boolean op,boolean permitted){if(!online||!op||!permitted)throw new SecurityException("オンラインの許可済み管理者が必要です。");}private static void rollbackLoadedWorld(World world){World fallback=Bukkit.getWorlds().stream().filter(w->!w.equals(world)).findFirst().orElseThrow(()->new IllegalStateException("帰還先ワールドがありません。"));for(var player:world.getPlayers())player.teleport(fallback.getSpawnLocation());if(!Bukkit.unloadWorld(world,false))throw new IllegalStateException("一時ワールドをアンロードできません。");}public boolean isTool(ItemStack item){return item!=null&&item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().has(key,PersistentDataType.BYTE);}private<T>T execute(java.util.concurrent.Callable<T> task){try{return executor.execute(task,Duration.ofSeconds(5));}catch(Exception e){throw new MapIoException("PAPER_WORLD","Paperワールド操作に失敗しました。",e);}}}
